-- Le 164 fatture del 2026 entrano in appoggio
--
-- Prima in una tabella di passaggio, non direttamente in `invoices`: così il
-- travaso si può guardare, contare e confrontare con l'archivio prima che
-- diventi contabilità. La tabella si butta quando ha finito.
--
-- Due eccezioni che l'archivio porta con sé:
--
-- **2.978 compare su due documenti diversi** — KERING Eyewear e VERSACE Orlando —
-- e tutte e due le cartelle dicono 2.978. Uno dei due è archiviato col numero
-- sbagliato, e non so quale: entrano entrambi in appoggio, ne passa uno solo nel
-- registro, e l'altro resta qui a chiedere il suo numero.
--
-- **3.086 non ha una data leggibile**: il documento scrive «September 25TH, 2026»
-- con le lettere maiuscole, e l'estrattore legge i mesi in inglese ma non quel
-- «TH». La data è quella, e la scrivo: non è un'ipotesi, è una lettura fatta a
-- occhio su un documento che ce l'ha.
-- ═══════════════════════════════════════════════════════════════════════════

drop table if exists public.import_fatture;
create table public.import_fatture (
  numero text, data date, cliente text, sito_doc text, valuta text,
  totale numeric(14,2), iva numeric(14,2), termini integer, po text,
  riga serial primary key
);
alter table public.import_fatture enable row level security;

